<section class="guest-form-card smart-home-panel" data-smart-home data-storage-key="luma-smart-home-{{ $company->id }}-{{ app('guestStay')->guest_stay_id }}">
    <div class="smart-home-heading"><div><span class="eyebrow">{{ __('guest.smart_home_eyebrow') }}</span><h2>{{ __('guest.smart_home_title') }}</h2><p>{{ __('guest.smart_home_intro') }}</p></div><span class="smart-demo-badge"><i class="bi bi-broadcast-pin"></i>{{ __('guest.demo_mode') }}</span></div>
    <div class="smart-home-scenes">
        @foreach(['welcome'=>'bi-door-open','relax'=>'bi-cup-hot','sleep'=>'bi-moon-stars','away'=>'bi-lock'] as $scene=>$icon)<button type="button" data-smart-scene="{{ $scene }}"><i class="bi {{ $icon }}"></i><span>{{ __('guest.smart_scene_'.$scene) }}</span></button>@endforeach
    </div>
    <div class="smart-home-grid">
        <article class="smart-control-card wide"><div class="smart-control-title"><span><i class="bi bi-lightbulb"></i></span><div><strong>{{ __('guest.smart_lighting') }}</strong><small>{{ __('guest.smart_lighting_hint') }}</small></div></div><div class="smart-toggle-row"><label><span>{{ __('guest.smart_main_light') }}</span><input type="checkbox" data-smart-key="mainLight" checked><i></i></label><label><span>{{ __('guest.smart_bedside_light') }}</span><input type="checkbox" data-smart-key="bedsideLight" checked><i></i></label></div><label class="smart-range"><span>{{ __('guest.smart_brightness') }} <b data-smart-output="brightness">70%</b></span><input type="range" min="0" max="100" step="5" value="70" data-smart-key="brightness"></label></article>
        <article class="smart-control-card"><div class="smart-control-title"><span><i class="bi bi-window"></i></span><div><strong>{{ __('guest.smart_curtains') }}</strong><small>{{ __('guest.smart_curtains_hint') }}</small></div></div><div class="smart-segmented">@foreach(['open','half','closed'] as $position)<label><input type="radio" name="smart_curtains" value="{{ $position }}" data-smart-key="curtains" @checked($position==='open')><span>{{ __('guest.smart_curtains_'.$position) }}</span></label>@endforeach</div></article>
        <article class="smart-control-card"><div class="smart-control-title"><span><i class="bi bi-thermometer-half"></i></span><div><strong>{{ __('guest.smart_climate') }}</strong><small>{{ __('guest.smart_climate_hint') }}</small></div></div><label class="smart-power"><span>{{ __('guest.smart_climate_power') }}</span><input type="checkbox" data-smart-key="climate" checked><i></i></label><label class="smart-range"><span>{{ __('guest.smart_temperature') }} <b data-smart-output="temperature">23°C</b></span><input type="range" min="16" max="30" step="1" value="23" data-smart-key="temperature"></label></article>
        <article class="smart-control-card wide"><div class="smart-control-title"><span><i class="bi bi-shield-check"></i></span><div><strong>{{ __('guest.smart_privacy') }}</strong><small>{{ __('guest.smart_privacy_hint') }}</small></div></div><div class="smart-toggle-row"><label><span>{{ __('guest.smart_do_not_disturb') }}</span><input type="checkbox" data-smart-key="doNotDisturb"><i></i></label><label><span>{{ __('guest.smart_night_light') }}</span><input type="checkbox" data-smart-key="nightLight"><i></i></label></div></article>
    </div>
    <div class="smart-home-feedback"><i class="bi bi-check2-circle"></i><span data-smart-feedback>{{ __('guest.smart_home_ready') }}</span></div>
