@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-smart-home]').forEach(panel=>{const defaults={mainLight:true,bedsideLight:true,brightness:70,curtains:'open',climate:true,temperature:23,doNotDisturb:false,nightLight:false};let state={...defaults};try{state={...state,...JSON.parse(localStorage.getItem(panel.dataset.storageKey)||'{}')}}catch(e){}const feedback=panel.querySelector('[data-smart-feedback]');const sync=()=>{panel.querySelectorAll('[data-smart-key]').forEach(input=>{const key=input.dataset.smartKey;if(input.type==='radio')input.checked=state[key]===input.value;else if(input.type==='checkbox')input.checked=Boolean(state[key]);else input.value=state[key];});panel.querySelector('[data-smart-output="brightness"]').textContent=state.brightness+'%';panel.querySelector('[data-smart-output="temperature"]').textContent=state.temperature+'°C';try{localStorage.setItem(panel.dataset.storageKey,JSON.stringify(state))}catch(e){}};const changed=message=>{feedback.textContent=message;panel.querySelector('.smart-home-feedback').classList.add('is-saved');setTimeout(()=>panel.querySelector('.smart-home-feedback').classList.remove('is-saved'),900);sync();};panel.addEventListener('change',event=>{const input=event.target.closest('[data-smart-key]');if(!input)return;state[input.dataset.smartKey]=input.type==='checkbox'?input.checked:(input.type==='range'?Number(input.value):input.value);changed(@json(__('guest.smart_home_saved')));});panel.addEventListener('input',event=>{const input=event.target.closest('input[type="range"][data-smart-key]');if(!input)return;state[input.dataset.smartKey]=Number(input.value);sync();});panel.addEventListener('click',event=>{const button=event.target.closest('[data-smart-scene]');if(!button)return;const scenes={welcome:{mainLight:true,bedsideLight:true,brightness:85,curtains:'open',climate:true,temperature:23,doNotDisturb:false,nightLight:false},relax:{mainLight:true,bedsideLight:true,brightness:35,curtains:'half',climate:true,temperature:23,doNotDisturb:false,nightLight:false},sleep:{mainLight:false,bedsideLight:false,brightness:0,curtains:'closed',climate:true,temperature:22,doNotDisturb:true,nightLight:true},away:{mainLight:false,bedsideLight:false,brightness:0,curtains:'closed',climate:false,temperature:24,doNotDisturb:true,nightLight:false}};state={...state,...scenes[button.dataset.smartScene]};panel.querySelectorAll('[data-smart-scene]').forEach(item=>item.classList.toggle('active',item===button));changed(@json(__('guest.smart_scene_applied')));});sync();});});
</script>
@endpush
